use gpui_kit::{AssetSource, SharedString};
use std::borrow::Cow;

/// MDI SVGs generated by `scripts/gen-mdi-icons.mjs`.
#[derive(rust_embed::RustEmbed)]
#[folder = "assets"]
#[include = "mdi/**/*.svg"]
pub struct MdiAssets;

/// Application asset source: MDI first, then the gpui-kit Lucide catalog.
#[derive(Clone, Copy, Debug, Default)]
pub struct AppAssets;

impl AssetSource for AppAssets {
    fn load(&self, path: &str) -> gpui_kit::Result<Option<Cow<'static, [u8]>>> {
        if let Some(file) = MdiAssets::get(path) {
            return Ok(Some(file.data));
        }
        gpui_kit::assets::Assets.load(path)
    }

    fn list(&self, path: &str) -> gpui_kit::Result<Vec<SharedString>> {
        let mut names: Vec<SharedString> = MdiAssets::iter()
            .filter(|name| name.starts_with(path))
            .map(Into::into)
            .collect();
        names.extend(gpui_kit::assets::Assets.list(path)?);
        Ok(names)
    }
}

/// Path for an MDI icon, e.g. `mdi("history")` -> `mdi/history.svg`.
pub fn mdi(name: &str) -> SharedString {
    format!("mdi/{name}.svg").into()
}
